/**
 * PostMessageTransport - for embedded iframe mode
 *
 * Communicates with parent window via postMessage API
 */

import type {
  UiTxTransport,
  UiTxRequest,
  UiTxResponse,
  PostMessageTransportOptions,
} from "./types";

export class PostMessageTransport implements UiTxTransport {
  private pending = new Map<
    string,
    { resolve: (value: unknown) => void; reject: (error: unknown) => void }
  >();
  private targetWindow: Window;
  private targetOrigin: string;
  private timeout: number;
  private messageHandler: (event: MessageEvent) => void;

  constructor(
    targetWindow: Window = window.parent,
    options: PostMessageTransportOptions = {}
  ) {
    this.targetWindow = targetWindow;
    this.targetOrigin = options.targetOrigin || "*";
    this.timeout = options.timeout || 30000;

    // Set up message listener
    this.messageHandler = this.handleResponse.bind(this);
    window.addEventListener("message", this.messageHandler);
  }

  async send<TReq, TRes>(request: UiTxRequest<TReq>): Promise<TRes> {
    const requestId = request.requestId;

    return new Promise<TRes>((resolve, reject) => {
      // Wrap resolve/reject to handle timeout cleanup
      let timeoutId: ReturnType<typeof setTimeout> | null = null;

      const wrappedResolve = (value: unknown) => {
        if (timeoutId) clearTimeout(timeoutId);
        resolve(value as TRes);
      };

      const wrappedReject = (error: unknown) => {
        if (timeoutId) clearTimeout(timeoutId);
        reject(error);
      };

      // Store promise resolvers
      this.pending.set(requestId, {
        resolve: wrappedResolve,
        reject: wrappedReject,
      });

      // Send message to parent (wrap request in UITX_REQUEST envelope)
      this.targetWindow.postMessage(
        {
          type: "UITX_REQUEST",
          request: {
            type: request.type,
            payload: request.payload,
            requestId,
          },
        },
        this.targetOrigin
      );

      // Timeout handling
      timeoutId = setTimeout(() => {
        if (this.pending.has(requestId)) {
          this.pending.delete(requestId);
          wrappedReject({
            code: "INTERNAL_ERROR",
            message: "Request timeout",
          });
        }
      }, this.timeout);
    });
  }

  private handleResponse(event: MessageEvent) {
    // Only process UITX_RESPONSE messages
    if (event.data?.type !== "UITX_RESPONSE") {
      return;
    }

    const response = event.data as UiTxResponse;
    const { requestId, ok, result, error } = response;

    const handler = this.pending.get(requestId);
    if (handler) {
      this.pending.delete(requestId);
      if (ok) {
        handler.resolve(result);
      } else {
        handler.reject(
          error || { code: "INTERNAL_ERROR", message: "Unknown error" }
        );
      }
    }
  }

  /**
   * Cleanup - remove event listener
   * Call this when transport is no longer needed
   */
  destroy() {
    window.removeEventListener("message", this.messageHandler);
    this.pending.clear();
  }
}
