/**
 * UiTx - Main client SDK class
 *
 * Capability-based client SDK for querying and mutating zDocs data
 */

import type { UiTxTransport } from "../transports";
import type {
  UiTxSession,
  EntityResponseList,
  GetEntityResponse,
  ListDocumentsResponse,
  QueryResponse,
  AggregateResponse,
  UpdateEntityFieldsResponse,
  CreateReconciliationLinkResponse,
  ListReconciliationLinksResponse,
  TraceReconciliationResponse,
  EntityObj,
  ConfirmResponse,
} from "../types";
import type { EntityType } from "@zdocs/types";

export class UiTx {
  constructor(private transport: UiTxTransport) { }

  /**
   * Get current session info (non-sensitive)
   */
  async getSession(): Promise<UiTxSession> {
    return this.transport.send({
      type: "getSession",
      payload: {},
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Search entities using existing search infrastructure
   */
  async searchEntities(params: {
    query: string;
    limit?: number;
    offset?: number;
    filters?: {
      docType?: string | string[];
      schemaType?: string | string[];
      entityType?: EntityType | EntityType[];
      folderId?: string | string[];
      date?: { gte?: string; lte?: string };
      amount?: { gte?: number; lte?: number };
      currency?: string | string[];
      isDataset?: boolean;
    };
    orderBy?: {
      field: "date" | "amount" | "relevance";
      dir: "asc" | "desc";
    };
  }): Promise<EntityResponseList> {
    return this.transport.send({
      type: "searchEntities",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Get full entity data with schema
   */
  async getEntity(params: { entityId: string }): Promise<GetEntityResponse> {
    return this.transport.send({
      type: "getEntity",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * List documents with filters
   */
  async listDocuments(params?: {
    docType?: string | string[];
    folderId?: string | string[];
    date?: { gte?: string; lte?: string };
    amount?: { gte?: number; lte?: number };
    currency?: string | string[];
    isDataset?: boolean;
    orderBy?: {
      field: "documentDate" | "createdAt" | "totalAmount";
      dir: "asc" | "desc";
    };
    limit?: number;
    offset?: number;
  }): Promise<ListDocumentsResponse> {
    return this.transport.send({
      type: "listDocuments",
      payload: params || {},
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Higher-level query builder
   */
  async query(params: {
    from: "documents" | "entities" | "reconciliation_links";
    select: string[];
    where?: Array<{
      field: string;
      op: "=" | "in" | ">" | ">=" | "<" | "<=" | "contains";
      value: unknown;
    }>;
    limit?: number;
    offset?: number;
    dateFrom?: string;
    dateTo?: string;
    orderBy?: { field: string; dir: "asc" | "desc" };
  }): Promise<QueryResponse> {
    return this.transport.send({
      type: "query",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Aggregation operations
   */
  async aggregate(params: {
    from: "documents" | "entities";
    metrics: Array<{
      op: "count" | "sum" | "avg";
      field?: string;
      as: string;
    }>;
    groupBy?: string[];
    where?: Array<{
      field: string;
      op: "=" | "in" | ">" | ">=" | "<" | "<=";
      value: unknown;
    }>;
    limit?: number;
  }): Promise<AggregateResponse> {
    return this.transport.send({
      type: "aggregate",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Update entity fields
   */
  async updateEntityFields(params: {
    entityId: string;
    changes: Record<string, unknown>;
  }): Promise<UpdateEntityFieldsResponse> {
    return this.transport.send({
      type: "updateEntityFields",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Create a reconciliation link
   */
  async createReconciliationLink(params: {
    sourceRef: EntityObj;
    targetRef: EntityObj;
    amount: number;
    currency: string;
    edgeType?: string;
    metadata?: Record<string, unknown>;
  }): Promise<CreateReconciliationLinkResponse> {
    return this.transport.send({
      type: "createReconciliationLink",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * List reconciliation links for an entity
   */
  async listReconciliationLinks(params?: {
    entityId?: string;
    schemaType?: string;
    limit?: number;
  }): Promise<ListReconciliationLinksResponse> {
    return this.transport.send({
      type: "listReconciliationLinks",
      payload: params || {},
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * Trace money flow from an entity
   */
  async traceReconciliation(params: {
    startEntityId: string;
    direction?: "both" | "incoming" | "outgoing";
    maxDepth?: number;
  }): Promise<TraceReconciliationResponse> {
    return this.transport.send({
      type: "traceReconciliation",
      payload: params,
      requestId: crypto.randomUUID(),
    });
  }

  /**
   * UI helpers - only work in embedded mode
   */
  ui = {
    /**
     * Show toast notification
     * Supports two call signatures:
     * - toast({ message: "...", level: "success" }) - object format
     * - toast("message", "success") - positional arguments format
     */
    toast: async (
      paramsOrMessage:
        | { message: string; level?: "info" | "success" | "warning" | "error" }
        | string,
      level?: "info" | "success" | "warning" | "error"
    ): Promise<void> => {
      // Normalize to object format
      const payload =
        typeof paramsOrMessage === "string"
          ? { message: paramsOrMessage, level: level || "info" }
          : paramsOrMessage;

      return this.transport.send({
        type: "ui.toast",
        payload,
        requestId: crypto.randomUUID(),
      });
    },

    /**
     * Show confirmation dialog
     */
    confirm: async (params: {
      title: string;
      message: string;
      confirmText?: string;
      cancelText?: string;
    }): Promise<ConfirmResponse> => {
      return this.transport.send({
        type: "ui.confirm",
        payload: params,
        requestId: crypto.randomUUID(),
      });
    },

    /**
     * Open entity in main app
     */
    openEntity: async (params: { entityId: string }): Promise<void> => {
      return this.transport.send({
        type: "ui.openEntity",
        payload: params,
        requestId: crypto.randomUUID(),
      });
    },

    /**
     * Open document in main app
     */
    openDocument: async (params: { documentId: string }): Promise<void> => {
      return this.transport.send({
        type: "ui.openDocument",
        payload: params,
        requestId: crypto.randomUUID(),
      });
    },

    openFolder: async (params: { folderId: string }): Promise<void> => {
      return this.transport.send({
        type: "ui.openFolder",
        payload: params,
        requestId: crypto.randomUUID(),
      });
    },

    /**
     * Upload a file to a folder in main app
     */
    uploadToFolder: async (params: { folderId: string }): Promise<void> => {
      return this.transport.send({
        type: "ui.uploadToFolder",
        payload: params,
        requestId: crypto.randomUUID(),
      });
    },
  };
}
