import { UiTx } from "./UiTx";
import { PostMessageTransport } from "../transports/PostMessageTransport";

const transport = new PostMessageTransport(window.parent, {
  targetOrigin: "*", // or lock this down later
});

const uiTx = new UiTx(transport);

(window as any).zDocs = {
  uiTx,
  version: "1.0.0",
  mode: "embedded",
};
